mapper.insert:

	SELECT SEQ_CHAT_MESSAGE.NEXTVAL FROM DUAL


INSERT 
  INTO 
       CHAT_MESSAGE (
					 MESSAGE_ID
				   , ROOM_ID
				   , PARTICIPANT_ID
				   , CONTENT
				   , MSG_TYPE
				   , CREATED_AT
				   )
VALUES (
		 #{messageId}
	   , #{roomId}
	   , #{participantId}
	   , #{content}
	   , #{msgType}
	   , SYSTIMESTAMP
	   )

mapper.select:
SELECT * FROM ( SELECT M.MESSAGE_ID , M.PARTICIPANT_ID , NVL(P.NICKNAME, '알 수 없음') AS NICKNAME , M.CONTENT , M.MSG_TYPE , M.CREATED_AT FROM CHAT_MESSAGE M LEFT JOIN PARTICIPANT P ON P.PARTICIPANT_ID = M.PARTICIPANT_ID WHERE M.ROOM_ID = #{roomId}
AND M.MESSAGE_ID > #{afterMessageId}
ORDER BY M.MESSAGE_ID DESC FETCH FIRST 100 ROWS ONLY ) ORDER BY MESSAGE_ID
